package com.wizzadrds.theworldremembers.chronicle; import com.wizzadrds.theworldremembers.family.*; import com.wizzadrds.theworldremembers.memory.*; import com.wizzadrds.theworldremembers.relationship.*; import com.wizzadrds.theworldremembers.village.*; import net.minecraft.server.level.ServerPlayer; import java.util.*; public final class ChronicleManager{private ChronicleManager(){} public static ChronicleBook build(ServerPlayer p){var s=p.server;var mm=MemoryManager.get(s);var rm=RelationshipManager.get(s);var fm=FamilyManager.get(s);var vm=VillageManager.get(s);var hm=VillageHistoryManager.get(s);var em=VillageEventManager.get(s);var timeline=new ArrayList<ChronicleEntry>();var people=new LinkedHashSet<String>();var rels=new ArrayList<String>();var fams=new ArrayList<String>();var villages=new ArrayList<String>();var memories=mm.memoriesOf(p.getUUID());for(var m:memories){people.add(m.npcId().toString());timeline.add(new ChronicleEntry(m.gameTime(),"memory",m.type().name(),m.summary()));}for(var r:fm.getRelations(p.getUUID())){fams.add(r.type().name()+" → "+(r.npcId().equals(p.getUUID())?r.relatedNpcId():r.npcId()));}for(var v:vm.all()){villages.add(v.villageId()+" population="+v.population()+" peak="+(hm.get(v.villageId())==null?0:hm.get(v.villageId()).peakPopulation()));for(var e:em.get(v.villageId()))timeline.add(new ChronicleEntry(e.tick(),"village",e.type(),e.position().toShortString()));}var all=rm;for(var id:people){try{var rel=all.get(UUID.fromString(id),p.getUUID());if(rel!=null)rels.add(id+" trust="+rel.trust()+" fear="+rel.fear()+" affection="+rel.affection());}catch(IllegalArgumentException ignored){}}timeline.sort(Comparator.comparingLong(ChronicleEntry::tick).thenComparing(ChronicleEntry::category).thenComparing(ChronicleEntry::title));return new ChronicleBook(timeline, new ArrayList<>(people), rels, fams, villages);}}